// src/backend/services/user.service.ts
import { User, UserAttributes, UserModel } from '../db/database';

// 'id' is omitted because it's typically auto-generated by the database.
type UserCreationAttributes = Omit<UserAttributes, 'id'>;

export class UserService {
  constructor() {
    // dependencies go here
  }

  /**
   * Creates a new user.
   * @param data - Data for the new user, excluding 'id'.
   * @returns The created user instance.
   */
  public async createUser(data: UserCreationAttributes): Promise<UserModel> {
    try {
      const newUser = await User.create(data as UserAttributes);
      console.log(`User created with ID: ${newUser.id}`);
      return newUser;
    } catch (error) {
      console.error('Error creating user:', this.formatError(error));
      throw new Error('Failed to create user.'); // Or a custom error class
    }
  }

  /**
   * Retrieves a user by their primary key (ID).
   * @param id - The UUID of the user.
   * @returns The user instance if found, otherwise null.
   */
  public async getUserById(id: string): Promise<UserModel | null> {
    try {
      const user = await User.findByPk(id);
      return user;
    } catch (error) {
      console.error(`Error fetching user with ID ${id}:`, this.formatError(error));
      throw new Error('Failed to fetch user by ID.');
    }
  }

  /**
   * Retrieves a user by their DID.
   * @param did - The DID of the user.
   * @returns The user instance if found, otherwise null.
   */
  public async getUserByDid(did: string): Promise<UserModel | null> {
    try {
      const user = await User.findOne({ where: { did } });
      return user;
    } catch (error) {
      console.error(`Error fetching user with DID ${did}:`, this.formatError(error));
      throw new Error('Failed to fetch user by DID.');
    }
  }

  /**
   * Retrieves all users, optionally filtering by user type.
   * @param userType - Optional filter for 'admin' or 'technician'.
   * @returns An array of user instances.
   */
  public async getAllUsers(userType?: 'admin' | 'technician'): Promise<UserModel[]> {
    try {
      const whereClause: Partial<UserAttributes> = {};
      if (userType) {
        whereClause.userType = userType;
      }
      const users = await User.findAll({ where: whereClause });
      return users;
    } catch (error) {
      console.error('Error fetching all users:', this.formatError(error));
      throw new Error('Failed to fetch all users.');
    }
  }

  /**
   * Updates an existing user.
   * @param id - The ID of the user to update.
   * @param data - An object containing the fields to update. 'id' and 'did' cannot be updated.
   * @returns The updated user instance if found and updated, otherwise null.
   */
  public async updateUser(id: string, data: Partial<Omit<UserAttributes, 'id' | 'did'>>): Promise<UserModel | null> {
    try {
      const user = await User.findByPk(id);
      if (!user) {
        console.warn(`User with ID ${id} not found for update.`);
        return null;
      }

      // DID should generally be immutable. If 'did' is part of 'data', it's ignored.
      // The type `Partial<Omit<UserAttributes, 'id' | 'did'>>` already prevents 'did' and 'id'.

      await user.update(data);
      console.log(`User with ID ${id} updated.`);
      return user.reload();
    } catch (error) {
      console.error(`Error updating user with ID ${id}:`, this.formatError(error));
      throw new Error('Failed to update user.');
    }
  }

  /**
   * Deletes a user by their ID.
   * @param id - The ID of the user to delete.
   * @returns True if the user was deleted, false if the user was not found.
   */
  public async deleteUser(id: string): Promise<boolean> {
    try {
      const user = await User.findByPk(id);
      if (!user) {
        console.warn(`User with ID ${id} not found for deletion.`);
        return false;
      }
      await user.destroy();
      console.log(`User with ID ${id} deleted.`);
      return true;
    } catch (error) {
      console.error(`Error deleting user with ID ${id}:`, this.formatError(error));
      throw new Error('Failed to delete user.');
    }
  }

  /**
   * Helper to format error messages for logging.
   * @param error - The error object.
   * @returns A string representation of the error message.
   */
  private formatError(error: unknown): string {
    if (error instanceof Error) {
      // Sequelize validation errors often have more details in `error.errors`
      if ((error as any).errors && Array.isArray((error as any).errors)) {
        return (error as any).errors.map((e: any) => e.message).join(', ');
      }
      return error.message;
    }
    return String(error);
  }
}